import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestOMaiorEOMenor(unittest.TestCase):
    def test_o_maior_acha_o_numero_grande(self):
        """o_maior devolve o maior numero da lista, mesmo de uma lista de um item"""
        self.assertEqual(rodar()["o_maior"]([3, 9, 1]), 9)
        self.assertEqual(rodar()["o_maior"]([5]), 5)

    def test_o_menor_acha_o_numero_pequeno(self):
        """o_menor devolve o menor numero da lista, mesmo de uma lista de um item"""
        self.assertEqual(rodar()["o_menor"]([7, 2, 8]), 2)
        self.assertEqual(rodar()["o_menor"]([4]), 4)

    def test_empatados_no_topo_sem_empate(self):
        """quantos_empataram_no_topo devolve 1 quando o maior aparece uma vez"""
        self.assertEqual(rodar()["quantos_empataram_no_topo"]([3, 9, 1]), 1)

    def test_empatados_no_topo_com_empate(self):
        """quantos_empataram_no_topo devolve quantas vezes o maior aparece"""
        self.assertEqual(rodar()["quantos_empataram_no_topo"]([3, 9, 9]), 2)
        self.assertEqual(rodar()["quantos_empataram_no_topo"]([4]), 1)

